import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
var raiz = join(dirname(fileURLToPath(import.meta.url)), "..");
function carregarEnv() {
  let conteudo;
  try {
    conteudo = readFileSync(join(raiz, ".env"), "utf8");
  } catch {
    return;
  }
  for (const linhaBruta of conteudo.split(/\r?\n/)) {
    const linha = linhaBruta.trim();
    if (!linha || linha.startsWith("#")) continue;
    const idx = linha.indexOf("=");
    if (idx === -1) continue;
    const chave = linha.slice(0, idx).trim();
    let valor = linha.slice(idx + 1).trim();
    if (valor.startsWith('"') && valor.endsWith('"') || valor.startsWith("'") && valor.endsWith("'")) {
      valor = valor.slice(1, -1);
    }
    if (!(chave in process.env)) process.env[chave] = valor;
  }
}
carregarEnv();
var env = process.env;
var config = {
  porta: Number(env.PORT ?? 3e3),
  modo: env.MODO === "piloto" ? "piloto" : "demonstracao",
  repositorio: env.REPOSITORIO === "supabase" ? "supabase" : "local",
  // Onde guardar o estado de sessao. 'supabase' e obrigatorio em serverless
  // (Vercel). 'memoria' serve para dev local / servidor persistente.
  sessao: env.SESSAO === "supabase" ? "supabase" : "memoria",
  supabase: {
    url: env.SUPABASE_URL ?? "",
    anonKey: env.SUPABASE_ANON_KEY ?? "",
    serviceKey: env.SUPABASE_SERVICE_ROLE_KEY || void 0
  },
  // Provedor da redacao: template (gratis, deterministico) | gemini (Google AI,
  // tier gratis) | anthropic (Claude, pago). Se nao definido, infere pela chave
  // presente; sem chave nenhuma, fica no template.
  iaProvedor: (() => {
    const p2 = env.IA_PROVEDOR;
    if (p2 === "gemini" || p2 === "anthropic" || p2 === "template") return p2;
    if ((env.ANTHROPIC_API_KEY ?? "") !== "") return "anthropic";
    if ((env.GEMINI_API_KEY ?? "") !== "") return "gemini";
    return "template";
  })(),
  anthropic: {
    apiKey: env.ANTHROPIC_API_KEY ?? "",
    modelo: env.ANTHROPIC_MODELO ?? "claude-sonnet-5"
  },
  gemini: {
    apiKey: env.GEMINI_API_KEY ?? "",
    // flash-lite: rápido (~1s) e barato, ideal para redação. O alias -latest
    // acompanha a versão vigente (modelos datados saem de disponibilidade).
    modelo: env.GEMINI_MODELO ?? "gemini-flash-lite-latest"
  },
  whatsapp: {
    token: env.WHATSAPP_TOKEN ?? "",
    phoneNumberId: env.WHATSAPP_PHONE_NUMBER_ID ?? "",
    verifyToken: env.WHATSAPP_VERIFY_TOKEN ?? ""
  },
  // Sal para o hash da sessao. Nunca gravamos o remetente em claro (LGPD).
  salSessao: env.SAL_SESSAO ?? "demo-sal-trocar-no-piloto",
  // Token opcional para proteger a edicao de estoque quando publicada. Vazio =
  // painel aberto (edicao ao vivo livre, util na demonstracao presencial).
  adminToken: env.ADMIN_TOKEN ?? ""
};
var ehDemonstracao = config.modo === "demonstracao";
var usaIA = config.iaProvedor === "anthropic" && config.anthropic.apiKey !== "" || config.iaProvedor === "gemini" && config.gemini.apiKey !== "";

// src/dominio/texto.ts
function normalizar(texto) {
  return (texto ?? "").normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().trim();
}
function trigramas(texto) {
  const set = /* @__PURE__ */ new Set();
  const palavras = normalizar(texto).split(/[^a-z0-9]+/).filter(Boolean);
  for (const p2 of palavras) {
    const s2 = "  " + p2 + " ";
    for (let i2 = 0; i2 + 3 <= s2.length; i2++) set.add(s2.slice(i2, i2 + 3));
  }
  return set;
}
function similaridade(a2, b2) {
  const ta = trigramas(a2);
  const tb = trigramas(b2);
  if (ta.size === 0 || tb.size === 0) return 0;
  let inter = 0;
  for (const t2 of ta) if (tb.has(t2)) inter++;
  const uniao = ta.size + tb.size - inter;
  return uniao === 0 ? 0 : inter / uniao;
}

